$('#editForm').onsubmit=e=>{e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));data.difficulty=Number(data.difficulty);data.tags=tags(data.tags);data.listed=form.elements.listed.checked;if(!capability('chart.tags'))delete data.tags;if(!capability(data.listed?'chart.publish':'chart.hide'))delete data.listed;task(e.submitter,async()=>{await api('/api/admin/charts/'+editId,jsonOptions('PATCH',data));$('#editDialog').close();toast('谱面信息已保存');await refresh()})};
