$('#addRecord').onclick=()=>{if(!state.charts.length){toast('请先上传谱面',true);return}$('#recordDialog').showModal()};$('#recordForm').onsubmit=e=>{e.preventDefault();const form=e.target,f=new FormData(form),data={};for(const key of ['player','chart','score','accuracy','perfect','good','bad','miss','maxCombo'])data[key]=Number(f.get(key)||0);data.accuracy/=100;data.fullCombo=form.elements.fullCombo.checked;task(e.submitter,async()=>{await api('/api/admin/records',jsonOptions('POST',data));$('#recordDialog').close();form.reset();toast('本地成绩已保存');await refresh()})};
