$('#chartForm').onsubmit=e=>{e.preventDefault();const form=e.target,f=new FormData(form);for(const [key,value] of [...f.entries()])if(typeof value==='string'&&!value.trim())f.delete(key);task(e.submitter,async()=>{$('#uploadProgress').hidden=false;$('#uploadStatus').textContent='上传并解析中，请稍候…';$('#uploadResult').hidden=true;const controls=Array.from(form.elements);controls.forEach(el=>el.disabled=true);try{const result=await api('/api/admin/charts',{method:'POST',body:f});form.reset();fileChanged();const box=$('#uploadResult');box.className='callout';box.replaceChildren();const summary=document.createElement('strong');summary.textContent=result.collection?'合集导入完成：新增 '+result.created.length+' 张，跳过 '+result.skipped.length+' 个文件':'「'+result.name+'」上传成功';box.append(summary);if(result.collection&&result.skipped.length){const ul=document.createElement('ul');result.skipped.forEach(item=>{const li=document.createElement('li');li.textContent=typeof item==='string'?item:(item.file||item.filename||item.name||'文件')+'：'+(item.reason||item.error||'已跳过');ul.append(li)});box.append(ul)}box.hidden=false;toast(summary.textContent)}catch(error){$('#uploadResult').textContent='上传未完成：'+error.message;$('#uploadResult').className='callout error';$('#uploadResult').hidden=false;throw error}finally{controls.forEach(el=>el.disabled=false);$('#uploadProgress').hidden=true;$('#uploadStatus').textContent=''}await refresh()})};
$('#connectForm').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{await refresh();const token=$('#token').value.trim();storage.set('localStorage',TOKEN_KEY,$('#rememberToken').checked?token:'');storage.set('sessionStorage',TOKEN_KEY,$('#rememberToken').checked?'':token);toast('已连接到「'+currentName()+'」');showView('charts')})};$('#forgetToken').onclick=()=>{if(state.busy)return;storage.set('localStorage',TOKEN_KEY,'');storage.set('sessionStorage',TOKEN_KEY,'');$('#token').value='';$('#rememberToken').checked=false;state.instances=[];state.charts=[];state.records=[];state.selected.clear();$('#loadError').hidden=true;$('#lastUpdated').textContent='等待连接';setConnected(false);render();toast('已清除当前浏览器的连接凭据')};

