$('#showLogin').onclick=()=>{$('#loginForm').hidden=false;$('#registerForm').hidden=true;$('#authError').hidden=true;$('#showLogin').className='primary';$('#showRegister').className='ghost'};
$('#showRegister').onclick=()=>{$('#loginForm').hidden=true;$('#registerForm').hidden=false;$('#authError').hidden=true;$('#showLogin').className='ghost';$('#showRegister').className='primary'};
function clearSession(){reviewUserId=null;permissionsUserId=null;$$('dialog').forEach(d=>d.close());for(const id of ['editForm','recordForm','chartForm','instanceForm','applicationForm','reviewForm','permissionsForm'])$('#'+id).reset();fileChanged();resetFilters();state.user=null;clearPolicyCache();state.csrf='';state.instances=[];state.charts=[];state.records=[];state.users=[];state.selected.clear();$('#token').value='';storage.set('localStorage',TOKEN_KEY,'');storage.set('sessionStorage',TOKEN_KEY,'');setConnected(false);$('#workspace').hidden=true;$('#authGate').hidden=false;$('#passwordForm').reset();render()}
async function enterSession(session){state.user=session.user;state.csrf=session.csrf;$('#token').value='';storage.set('localStorage',TOKEN_KEY,'');storage.set('sessionStorage',TOKEN_KEY,'');$('#authGate').hidden=true;$('#workspace').hidden=false;await refresh();showView(awaitingApproval()?'application':state.instances.length?'charts':'instances')}
for(const [id,action] of [['loginForm','login'],['registerForm','register'],['setupForm','setup']])$('#'+id).onsubmit=e=>{e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));if(data.confirmPassword!==undefined&&data.password!==data.confirmPassword){$('#authError').textContent='两次输入的密码不一致';$('#authError').hidden=false;return}delete data.confirmPassword;if(action==='register'){data.application=readApplication(form);for(const key of ['reason','useType','organization','socialAccount','notes'])delete data[key]}task(e.submitter,async()=>{try{$('#authError').hidden=true;const session=await api('/api/admin/auth/'+action,jsonOptions('POST',data));form.reset();await enterSession(session);toast(action==='login'?'欢迎回来':action==='setup'?'超级管理员已创建':'注册申请已提交，请等待审核')}catch(error){$('#authError').textContent=error.message;$('#authError').hidden=false;throw error}})};
$('#logoutButton').onclick=e=>task(e.currentTarget,async()=>{await api('/api/admin/auth/logout',jsonOptions('POST',{}));clearSession();toast('已退出登录')});
